/**
 * Redirect exact legacy English paths before plugins/canonical logic can send them home.
 */
function justice_theme_exact_legacy_path_redirect() {
	if ( is_admin() || wp_doing_ajax() || wp_doing_cron() ) {
		return;
	}

	$req_path = $_SERVER['REQUEST_URI'] ?? '';
	$path_parts = explode( '?', $req_path );
	$path = trim( rawurldecode( $path_parts[0] ), '/' );

	$redirects = [
		'tax-law'         => 'tax-lawyer',
		'personal-injury' => 'tort-lawyer',
	];

	if ( isset( $redirects[ $path ] ) ) {
		wp_safe_redirect( home_url( '/' . $redirects[ $path ] . '/' ), 301 );
		exit;
	}
}
add_action( 'init', 'justice_theme_exact_legacy_path_redirect', -3001 );

/**
 * Hook into template_redirect to perform the native 301 redirect
 */
function justice_theme_native_slug_redirect() {
	if ( is_admin() ) {
		return;
	}

	// Only intercept 404s or general requests if needed.
	// Actually, WP might 404 on the old slug. Let's run on parse_request or template_redirect.
	// If it's a 404, check our map.
	if ( is_404() ) {
		$req_path = $_SERVER['REQUEST_URI'] ?? '';
		$path_parts = explode( '?', $req_path );
		$path = trim( $path_parts[0], '/' ); // e.g. "articles/hebrew-slug"

		// Extract just the slug
		$segments = explode( '/', $path );
		$slug = urldecode( end( $segments ) );

		$redirects = justice_theme_get_slug_redirects();

		if ( isset( $redirects[ $slug ] ) ) {
			$new_slug = $redirects[ $slug ];
			// Preserve the rest of the path (e.g. /articles/...)
			array_pop( $segments );
			$segments[] = $new_slug;
			
			$new_url = home_url( '/' . implode( '/', $segments ) . '/' );
			
			wp_redirect( $new_url, 301 );
			exit;
		}
	}
}
add_action( 'template_redirect', 'justice_theme_native_slug_redirect', -3000 );
